ST.xhtml:p:
(*开浮动*)
RTrigger1(CLK := g_bSustain4Follow OR bSustain4Follow);
RTrigger2(CLK := g_bSustain5Follow OR bSustain5Follow);
RTrigger3(CLK := g_bSustain6Follow OR bSustain6Follow);

(*关浮动*)
FTrigger1(CLK := bSustain4Follow);
FTrigger2(CLK := bSustain5Follow );
FTrigger3(CLK := bSustain6Follow);

IF RTrigger1.Q THEN
  nFollowState4 := 1;
END_IF;
IF RTrigger2.Q THEN
  nFollowState5 := 1;
END_IF;
IF RTrigger3.Q THEN
  nFollowState6 := 1;
END_IF;

IF FTrigger1.Q THEN
  nFollowState4 := 3;
END_IF;
IF FTrigger2.Q THEN
  nFollowState5 := 3;
END_IF;
IF FTrigger3.Q THEN
  nFollowState6 := 3;
END_IF;

g_SustainFollowIn4.CurHeight := 1.0;
g_SustainFollowIn5.CurHeight := 1.0;
g_SustainFollowIn6.CurHeight := 1.0;
fSetPos := g_fSustainTargetPos;
g_SustainFollowIn4.SetHeight := g_SustainFollowIn4.CurHeight;
g_SustainFollowIn5.SetHeight := g_SustainFollowIn5.CurHeight;
g_SustainFollowIn6.SetHeight := g_SustainFollowIn6.CurHeight;

g_SustainFollowIn4.Distance := -(fSetPos - dLastCoord);
g_SustainFollowIn5.Distance := -(fSetPos - dLastCoord);
g_SustainFollowIn6.Distance := -(fSetPos - dLastCoord);
dLastCoord := fSetPos;
CASE nFollowState4 OF
  0:
    nFollowState4 := 0;
  1:
    g_SustainFollowIn4.Execute := TRUE;
    IF g_SustainFollowIn4.Done THEN
      g_bSustain4InFollow := TRUE;
    END_IF;
    IF g_SustainFollowIn4.Error THEN
      (*IF g_SustainFollowIn4.ErrorId = 112 THEN
         ;
      END_IF;*)
      g_bSustain4InFollow := FALSE;
      g_SustainFollowIn4.Execute := FALSE;
      nFollowState4 := 0;
    END_IF;
  3:
    g_SustainFollowOut4.Execute := TRUE;
    g_SustainFollowIn4.Execute := FALSE;
    IF g_SustainFollowOut4.Done OR g_SustainFollowOut4.Error THEN
      g_bSustain4InFollow := FALSE;
      g_SustainFollowOut4.Execute := FALSE;
      nFollowState4 := 0;
    END_IF;
END_CASE;

CASE nFollowState5 OF
  0:
    nFollowState5 := 0;
  1:
    g_SustainFollowIn5.Execute := TRUE;
    IF g_SustainFollowIn5.Done THEN
      g_bSustain5InFollow := TRUE;
    END_IF;
    IF g_SustainFollowIn5.Error THEN
      (*IF g_SustainFollowIn5.ErrorId = 112 THEN
         ;
      END_IF;*)
      g_bSustain5InFollow := FALSE;
      g_SustainFollowIn5.Execute := FALSE;
      nFollowState5 := 0;
    END_IF;
  3:
    g_SustainFollowOut5.Execute := TRUE;
    g_SustainFollowIn5.Execute := FALSE;
    IF g_SustainFollowOut5.Done OR g_SustainFollowOut5.Error THEN
      g_bSustain5InFollow := FALSE;
      g_SustainFollowOut5.Execute := FALSE;
      nFollowState5 := 0;
    END_IF;
END_CASE;

CASE nFollowState6 OF
  0:
    nFollowState6 := 0;
  1:
    g_SustainFollowIn6.Execute := TRUE;
    IF g_SustainFollowIn6.Done THEN
      g_bSustain6InFollow := TRUE;
    END_IF;
    IF g_SustainFollowIn6.Error THEN
      (*IF g_SustainFollowIn6.ErrorId = 112 THEN
         ;
      END_IF;*)
      g_bSustain6InFollow := FALSE;
      g_SustainFollowIn6.Execute := FALSE;
      nFollowState6 := 0;
    END_IF;
  3:
    g_SustainFollowOut6.Execute := TRUE;
    g_SustainFollowIn6.Execute := FALSE;
    IF g_SustainFollowOut6.Done OR g_SustainFollowOut6.Error THEN
      g_bSustain6InFollow := FALSE;
      g_SustainFollowOut6.Execute := FALSE;
      nFollowState6 := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  g_SustainFollowIn4.Execute := FALSE;
  g_SustainFollowIn5.Execute := FALSE;
  g_SustainFollowIn6.Execute := FALSE;
  g_SustainFollowOut4.Execute := FALSE;
  g_SustainFollowOut5.Execute := FALSE;
  g_SustainFollowOut6.Execute := FALSE;
  g_bSustain4InFollow := FALSE;
  g_bSustain5InFollow := FALSE;
  g_bSustain6InFollow := FALSE;
END_IF;
